import("./tasks/drone/sim.mjs").then(async ({initialState}) => {
  const {trialParameters, random, TASK} = await import("./tasks/drone/task.mjs");
  const seed = 98765;
  const rng = random((seed ^ 0xa5a5a5a5) >>> 0);
  const state = initialState(trialParameters(seed));
