export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  let kT = 21.5;
  let uThrust = 0.45;
  let lastThrust = 0.45;
  let vyHat = 0, dyHat = 0;
  let vxHat = 0, dxHat = 0;
  let vzHat = 0, dzHat = 0;
  let init = false;

  let gateIdx = -1;
  let phase = 'approach';
  let alignCount = 0;
  let yawInt = 0;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (!init) {
        init = true;
        vxHat = v.x; vyHat = v.y; vzHat = v.z;
      }

      const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
      const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bodyX = sp * cr, bodyZ = -sr;
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = cp * cr;
      const dirZ = -sy * bodyX + cy * bodyZ;

      uThrust += (lastThrust - uThrust) * (1 - Math.exp(-dt / 0.038));
      const massHat = clamp(15.5 / kT, 0.60, 0.85);
      const dragCoeff = 0.42 / massHat;

      if (p.y > 0.085 && p.y < 2.90) {
        const ayModel = kT * uThrust * dirY - 9.81 - dragCoeff * v.y + dyHat;
        vyHat += ayModel * dt;
        const errVy = v.y - vyHat;
        vyHat += 0.45 * errVy;
        if (uThrust * dirY > 0.25) {
          kT = clamp(kT + 2.2 * errVy / (uThrust * dirY), 17.0, 27.0);
        }
        dyHat = clamp(dyHat + 3.0 * errVy, -2.5, 2.5);

        const specThrust = Math.max(0, kT * uThrust + dyHat);
        const axModel = specThrust * dirX - dragCoeff * v.x;
        const azModel = specThrust * dirZ - dragCoeff * v.z;

        vxHat += (axModel + dxHat) * dt;
        const errVx = v.x - vxHat;
        vxHat += 0.45 * errVx;
        dxHat = clamp(dxHat + 6.5 * errVx, -6.5, 6.5);

        vzHat += (azModel + dzHat) * dt;
        const errVz = v.z - vzHat;
        vzHat += 0.45 * errVz;
        dzHat = clamp(dzHat + 6.5 * errVz, -6.5, 6.5);
      } else {
        vxHat = v.x; vyHat = v.y; vzHat = v.z;
      }

      let tx = p.x, ty = 1.05, tz = p.z;
      let vxRef = 0, vyRef = 0, vzRef = 0;
      let maxTilt = 0.55;
      let touchDown = false;

      if (obs.gateIndex < 3) {
        const g = obs.nextGate.centre;
        if (gateIdx !== obs.gateIndex) {
          gateIdx = obs.gateIndex;
          phase = 'approach';
          alignCount = 0;
        }

        const dy = Math.abs(p.y - g.y);
        const dz = Math.abs(p.z - g.z);
        const tCross = clamp((g.x - p.x) / Math.max(0.45, v.x), 0.04, 0.22);
        const predDy = Math.abs(p.y + v.y * tCross - g.y);
        const predDz = Math.abs(p.z + v.z * tCross - g.z);

        // If we somehow crossed x >= g.x without passing the gate, go around safely
        if (p.x >= g.x - 0.01) {
          phase = 'recover';
          alignCount = 0;
        }

        if (phase === 'recover') {
          tx = g.x - 0.35;
          ty = g.y;
          tz = g.z + (p.z >= g.z ? 0.62 : -0.62);
          if (p.x < g.x - 0.22) {
            phase = 'approach';
          }
        } else if (phase === 'approach') {
          ty = g.y;
          tz = g.z;
          const yzErr = Math.hypot(p.y - g.y, p.z - g.z);
          // Keep x back slightly while yz error is large
          const stageX = g.x - clamp(0.24 + 0.35 * yzErr, 0.24, 0.55);
          tx = stageX;

          const aligned = p.x > g.x - 0.42 && dy < 0.075 && dz < 0.042 &&
                          predDy < 0.095 && predDz < 0.055 &&
                          Math.abs(v.y) < 0.25 && Math.abs(v.z) < 0.16;
          if (aligned) alignCount++;
          else alignCount = Math.max(0, alignCount - 1);

          if (alignCount >= 4) {
            phase = 'cross';
          }
        }

        if (phase === 'cross') {
          // Check if we need to abort before crossing due to a sudden gust
          const canStop = p.x + (Math.max(0, v.x) * Math.max(0, v.x)) / (2 * 3.8) < g.x - 0.04;
          const unsafe = (dz > 0.072 || predDz > 0.082 || dy > 0.13 || predDy > 0.15);
          if (p.x < g.x - 0.06 && canStop && unsafe) {
            phase = 'approach';
            alignCount = 0;
            tx = g.x - 0.28;
            ty = g.y;
            tz = g.z;
          } else {
            tx = g.x + 0.32;
            ty = g.y;
            tz = g.z;
            vxRef = 0.95;
          }
        }
      } else {
        const pad = obs.pad.centre;
        if (gateIdx !== 3) {
          gateIdx = 3;
          phase = 'pad_approach';
          alignCount = 0;
        }
        tx = pad.x;
        tz = pad.z;
        const padErr = Math.hypot(p.x - pad.x, p.z - pad.z);
        const hSpeed = Math.hypot(v.x, v.z);
        const speed3D = Math.hypot(v.x, v.y, v.z);

        if (phase === 'pad_approach') {
          // Smoothly descend as we approach the pad horizontally
          ty = clamp(0.22 + 0.55 * padErr, 0.22, 0.95);
          if (padErr < 0.11 && hSpeed < 0.25 && p.y < 0.35) {
            phase = 'pad_land';
          }
        }
        if (phase === 'pad_land') {
          if (padErr > 0.14 && p.y > 0.11) {
            phase = 'pad_approach';
            ty = 0.25;
          } else {
            // Controlled soft descent
            ty = 0.05;
            vyRef = clamp(-0.35 * (p.y - 0.06), -0.35, 0);
            maxTilt = 0.16;
            if (p.y <= 0.092 && padErr <= 0.135 && speed3D < 0.45) {
              touchDown = true;
            }
          }
        }
      }

      // Position error clamping for smooth velocity profile
      const ex = clamp(tx - p.x, -0.75, 0.75);
      const ey = clamp(ty - p.y, -0.75, 0.75);
      const ez = clamp(tz - p.z, -0.75, 0.75);

      const axDes = 6.2 * ex + 4.4 * (vxRef - vxHat);
      const azDes = 6.8 * ez + 4.6 * (vzRef - vzHat);
      const ayDes = 7.5 * ey + 4.8 * (vyRef - vyHat);

      const fxSpec = axDes + dragCoeff * vxHat - dxHat;
      const fzSpec = azDes + dragCoeff * vzHat - dzHat;
      const fySpec = clamp(9.81 + ayDes + dragCoeff * vyHat - dyHat, 3.5, 16.5);

      const fyActual = Math.max(5.5, fySpec);
      const uX = fxSpec / fyActual;
      const uZ = fzSpec / fyActual;

      const pitchDes = Math.atan(cy * uX - sy * uZ);
      const rollDes = Math.atan(-Math.cos(pitchDes) * (sy * uX + cy * uZ));

      let pitch = clamp(pitchDes + 0.30 * (pitchDes - att.pitch) - 0.035 * rates.pitch, -maxTilt, maxTilt);
      let roll = clamp(rollDes + 0.30 * (rollDes - att.roll) - 0.035 * rates.roll, -maxTilt, maxTilt);
      let thrust = clamp(fySpec / (kT * Math.max(0.55, cr * cp)), 0, 1);

      if (touchDown) {
        pitch = clamp(pitch, -0.13, 0.13);
        roll = clamp(roll, -0.13, 0.13);
        thrust = 0.15;
      }

      yawInt = clamp(yawInt + att.yaw * dt, -0.4, 0.4);
      const yawRate = clamp(-2.2 * att.yaw - 0.6 * yawInt, -2, 2);

      lastThrust = thrust;
      return { thrust, roll, pitch, yawRate };
    },
  };
}

