        const speed3D = Math.hypot(v.x, v.y, v.z);

        if (phase === 'pad_approach') {
          ty = clamp(0.22 + 0.55 * padErr, 0.22, 0.95);
          if (padErr < 0.095 && hSpeed < 0.22 && p.y < 0.32) {
            phase = 'pad_land';
          }
        }
        if (phase === 'pad_land') {
          if (padErr > 0.115) {
            phase = 'pad_approach';
            ty = 0.26;
          } else {
            ty = 0.045;
            vyRef = clamp(-0.32 * (p.y - 0.055), -0.32, 0);
