            }
          }
        }
      }

      const ex = clamp(tx - p.x, -0.70, 0.70);
      const ey = clamp(ty - p.y, -0.75, 0.75);
      const ez = clamp(tz - p.z, -0.65, 0.65);

      let axDes = 6.8 * ex + 5.2 * (vxRef - vxHat);
      if (emergencyBrakeX) {
        axDes = Math.min(axDes, -7.5 * Math.max(0.25, v.x) + 9.0 * (tx - p.x));
