      const rollDes = Math.atan(-Math.cos(pitchDes) * (sy * uX + cy * uZ));

      let pitch = clamp(pitchDes + 0.50 * (pitchDes - att.pitch) - 0.05 * rates.pitch, -maxTilt, maxTilt);
